const rows=[];for(const path of await walk(root)){const text=await fs.readFile(path,'"'"'utf8'"'"');rows.push({path,physicalLines:text.split('"'"'\n'"'"').length-(text.endsWith('"'"'\n'"'"')?1:0)});}
rows.sort((a,b)=>b.physicalLines-a.physicalLines);
const hash=crypto.createHash('"'"'sha256'"'"').update(await fs.readFile('"'"'scripts/count-loc.mjs'"'"')).digest('"'"'hex'"'"');
const expected='"'"'f73b6acb7d073e90631936ad62be8705a9c2a2f93c7e2097e7ca4f5c062f12ab'"'"';
const violations=rows.filter(row=>row.physicalLines>999);
const children=[];
for(const name of await fs.readdir('"'"'/proc'"'"')){
 if(!/^\d+$/.test(name)||Number(name)===process.pid)continue;
 try{const stat=await fs.readFile('"'"'/proc/'"'"'+name+'"'"'/stat'"'"','"'"'utf8'"'"');const found=stat.match(/^(\d+) \((.*?)\) ([A-Z]) (\d+)/);if(found&&['"'"'node'"'"','"'"'python3'"'"','"'"'chromium'"'"','"'"'chrome_crashpad'"'"','"'"'chromedriver'"'"','"'"'esbuild'"'"'].includes(found[2]))children.push({pid:Number(found[1]),command:found[2],state:found[3],ppid:Number(found[4])});}catch(error){if(error.code!=='"'"'ENOENT'"'"'&&error.code!=='"'"'ESRCH'"'"')throw error;}
}
const liveChildren=children.filter(row=>row.state!=='"'"'Z'"'"');
console.log(JSON.stringify({liveChildren,deadZ:children.filter(row=>row.state==='"'"'Z'"'"'),ok:!liveChildren.length},null,2));
if(liveChildren.length)process.exitCode=1;
console.log(JSON.stringify({counterSha256:hash,frozenMatch:hash===expected,files:rows.length,violations,largestPhysical:rows.slice(0,10),ok:hash===expected&&!violations.length},null,2));
if(hash!==expected||violations.length)process.exitCode=1;
